
(()=>{
'use strict';
const QS=new URLSearchParams(location.search), initialView=QS.get('view')||'studio';
const KEY='harmoniq-demo-multievent-v1', CHANNEL='harmoniq-demo-multievent-v1';
const COLORS={violet:'#7851e9',pink:'#e45fc2',teal:'#34c9b0',gold:'#fac779',blue:'#5c80ff'};
const sequence=[{at:0,label:'Violet pulse',color:COLORS.violet},{at:4,label:'Pink wave',color:COLORS.pink},{at:8,label:'Ocean glow',color:COLORS.teal},{at:12,label:'Finale',color:COLORS.gold}];
const baseline={activeTab:'overview',view:'studio',eventName:'MIDNIGHT FESTIVAL',attendees:86,color:COLORS.violet,lightMode:'idle',lightStarted:0,lightName:'Aurora Wave',poll:{question:'Which track should play next?',options:['Euphoria','Afterglow','The Final Beat'],votes:[13,8,3],open:false,version:1},quiz:{question:'What colour comes next in the Aurora Wave?',options:['Electric blue','Violet','Amber'],correct:1,open:false,version:1},announcement:'The next light moment starts in 2 minutes. Keep this page open to join the wave.',announcementSent:false,sponsorActive:false,rewardCount:18,lightLaunchCount:0,updated:Date.now()};

const TYPES={
 concert:{label:'Concert / Festival',modules:['lights','poll','quiz','announcements','sponsors','rewards','analytics','display'],description:'Audience colour, voting and sponsor activations'},
 corporate:{label:'Corporate Conference',modules:['poll','quiz','announcements','analytics','display'],description:'Q&A-style polls, training quizzes and reporting'},
 university:{label:'University Event',modules:['poll','quiz','announcements','analytics','display','rewards'],description:'Campus welcome, short quizzes and announcements'},
 pub:{label:'Pub / Quiz Night',modules:['poll','quiz','announcements','rewards','sponsors','analytics','display'],description:'Trivia, limited offers and quick polls'}
};
const MODULES={lights:'Light experience',poll:'Live polling',quiz:'Quiz & trivia',announcements:'Announcements',sponsors:'Sponsor moments',rewards:'Rewards & offers',analytics:'Basic analytics',display:'Live display',seating:'Seat & zone check-in',food:'Food discovery & orders'};
for(const t of Object.values(TYPES)){t.modules.push('seating','food')}
const SEQUENCES={
 aurora:{name:'Aurora Wave',stages:[{at:0,label:'Violet pulse',color:COLORS.violet},{at:4,label:'Pink wave',color:COLORS.pink},{at:8,label:'Ocean glow',color:COLORS.teal},{at:12,label:'Finale',color:COLORS.gold}],duration:16},
 focus:{name:'Focus Pulse',stages:[{at:0,label:'Teal focus',color:COLORS.teal},{at:3,label:'Blue rise',color:COLORS.blue},{at:6,label:'Violet focus',color:COLORS.violet},{at:9,label:'Blue finale',color:COLORS.blue}],duration:12}
};
function categoryOf(e){return TYPES[e?.category]?e.category:'concert'}
function enabledFor(e,key){return Boolean((e.modules||TYPES[categoryOf(e)].modules).includes(key))}
function defaultBank(cat){let x={concert:[{type:'choice',question:'Which track should play next?',options:['Euphoria','Afterglow','The Final Beat']},{type:'yesno',question:'Are you ready for the next light show?',options:['Yes','No']},{type:'choice',question:'Which moment was your favourite?',options:['Lighting','Music','Trivia']}],corporate:[{type:'choice',question:'Which session was most useful?',options:['Strategy','Innovation','Networking']},{type:'yesno',question:'Would you join another session?',options:['Yes','No']},{type:'choice',question:'What should we cover next?',options:['Technology','Leadership','Operations']}],university:[{type:'choice',question:'Which welcome activity comes next?',options:['Campus tour','Team quiz','Music']},{type:'yesno',question:'Did you find your welcome information?',options:['Yes','No']},{type:'choice',question:'Which club interests you?',options:['Sports','Arts','Technology']}],pub:[{type:'choice',question:'Choose tonight’s trivia theme',options:['Music','Sport','History']},{type:'yesno',question:'Ready for the final round?',options:['Yes','No']},{type:'choice',question:'Next theme?',options:['Movies','Food','Travel']}]}[cat]||[];return clone(x)}
function upgradeEvent(e){
 e.category=categoryOf(e);e.visibility=e.visibility==='private'?'private':'public';if(!Array.isArray(e.modules))e.modules=[...TYPES[e.category].modules];
 const s=e.state;if(!s)return;
 if(!Array.isArray(s.pollBank)||!s.pollBank.length)s.pollBank=defaultBank(e.category);
 if(!Number.isInteger(s.pollIndex))s.pollIndex=0;if(!Array.isArray(s.pollArchive))s.pollArchive=[];
 if(!Array.isArray(s.poll.votes))s.poll.votes=[];
 if(!s.sequenceId)s.sequenceId='aurora';
 if(!s.sponsor)s.sponsor={name:'NOVA AUDIO',headline:'BEYOND THE SOUND',offer:'10% off event merchandise',expiry:'',limit:25};
 if(!Array.isArray(s.claims))s.claims=[];
 if(!Array.isArray(s.feedback))s.feedback=[];
 if(!s.joinedSessions)s.joinedSessions=[];
 if(!Number.isFinite(s.quizResponses))s.quizResponses=0;
 if(!Number.isFinite(s.pollLaunchCount))s.pollLaunchCount=0;
 if(!Number.isFinite(s.messagesSent))s.messagesSent=0;
 if(!Array.isArray(s.seatAssignments))s.seatAssignments=[];
 if(!s.seatCheckins||Array.isArray(s.seatCheckins))s.seatCheckins={};
 if(!Array.isArray(s.zoneMessages))s.zoneMessages=[];
 if(!Array.isArray(s.foodOrders))s.foodOrders=[];
 if(!e.extensionsV3){for(const k of ['seating','food'])if(!e.modules.includes(k))e.modules.push(k);e.extensionsV3=true;}
 if(!e.extensionsV4){
  if(e.modules.includes('messaging')&&!e.modules.includes('announcements'))e.modules.push('announcements');
  e.modules=e.modules.filter(k=>k!=='messaging');
  const previous=(s.zoneMessages||[]).map(m=>({id:m.id||'oldzone-'+m.date,zone:m.zone||'all',text:m.text,date:m.date||Date.now(),active:true}));
  if(s.announcementSent&&s.announcement)previous.push({id:'oldall-'+(s.updated||Date.now()),zone:'all',text:s.announcement,date:s.updated||Date.now(),active:true});
  s.messages=[...(Array.isArray(s.messages)?s.messages:[]),...previous].sort((a,b)=>(a.date||0)-(b.date||0));
  e.extensionsV4=true;
 }
 if(!Array.isArray(s.messages))s.messages=[];
}
function makeSeedEvent(id,code,name,venue,date,category,status='live'){
 const e={id,code,name,venue,date,category,status,visibility:'public',modules:[...TYPES[category].modules],state:newEventState(name)};
 upgradeEvent(e);e.state.poll=Object.assign(e.state.poll,{...e.state.pollBank[0],votes:new Array(e.state.pollBank[0].options.length).fill(0),open:false});
 if(category==='corporate')e.state.quiz={question:'What is the focus of our innovation session?',options:['Customer value','Office furniture','Parking'],correct:0,open:false,version:1};
 if(category==='university')e.state.quiz={question:'Which service helps new students find their way?',options:['Welcome desk','Rewards programme','Lighting'],correct:0,open:false,version:1};
 return e;
}
function shareUrl(e){return location.origin+location.pathname+'?view=attendee&event='+encodeURIComponent(e.code)}
function realQR(data,size=160){try{const qr=new QRCode(-1,QRErrorCorrectLevel.M);qr.addData(data);qr.make();const n=qr.getModuleCount(),margin=4;let path='';for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(qr.isDark(y,x))path+='M'+(x+margin)+' '+(y+margin)+'h1v1h-1z';return '<svg role="img" aria-label="Scannable QR code" viewBox="0 0 '+(n+margin*2)+' '+(n+margin*2)+'" width="'+size+'" height="'+size+'" xmlns="http://www.w3.org/2000/svg"><rect width="100%" height="100%" fill="#fff"/><path fill="#181023" d="'+path+'"/></svg>'}catch(e){return '<span class="small" style="color:#321">QR unavailable: use event code</span>'}}
function eventShareSection(e){return '<div class="panel"><h2>Invite attendees</h2><p class="descr">Share a real QR or a dedicated event URL. Public events appear in the attendee lobby; private events are code/link only.</p><div class="share-row"><div class="qr-real">'+realQR(shareUrl(e))+'</div><div style="flex:1;min-width:185px"><div class="kicker">EVENT ACCESS · '+esc(e.visibility.toUpperCase())+'</div><p class="mono">'+esc(e.code)+'</p><p class="short-link">'+esc(shareUrl(e))+'</p><div class="row"><button class="btn secondary" data-action="copy-event-link">Copy invite link</button><button class="btn ghost" data-action="save-event-qr">Save QR</button></div></div></div></div>'}
function selectedReport(e){const s=e.state;const votes=(s.pollArchive||[]).reduce((sum,p)=>sum+p.votes.reduce((a,b)=>a+b,0),0)+s.poll.votes.reduce((a,b)=>a+b,0);const used=s.claims.filter(c=>c.used).length;const answered=Number(s.quizResponses||0);const ratings=s.feedback||[];const mean=ratings.length?(ratings.reduce((a,b)=>a+b.rating,0)/ratings.length).toFixed(1):'—';return {attendees:s.attendees,votes,answered,lightShows:s.lightLaunchCount,announcements:s.messagesSent,claims:s.claims.length,redeemed:used,feedback:ratings.length,avgRating:mean,seatCheckins:Object.values(s.seatCheckins||{}).filter(v=>v.confirmed).length,zoneMessages:(s.messages||[]).filter(m=>m.zone!=='all').length,foodOrders:(s.foodOrders||[]).length,foodPickup:(s.foodOrders||[]).filter(o=>o.status==='ready'||o.status==='collected').length,foodDelivery:(s.foodOrders||[]).filter(o=>o.service==='delivery').length}}

function clone(x){return JSON.parse(JSON.stringify(x))}
function newEventState(name,seed=false){
 const b=clone(baseline);b.eventName=name.toUpperCase();
 if(!seed){b.attendees=0;b.poll.votes=[0,0,0];b.poll.open=false;b.rewardCount=0;b.lightLaunchCount=0;}
 b.updated=Date.now();return b;
}
function seededDatabase(){
 const first=newEventState('Midnight Festival',true);
 try{const legacy=JSON.parse(localStorage.getItem('harmoniq-demo-state-v3')||'null');if(legacy?.poll&&legacy?.quiz)Object.assign(first,legacy)}catch(e){}
 const second=newEventState('City Beats Live');second.poll.question='Which act should play next?';second.poll.options=['Neon Echo','Northern Lights','Echo Pulse'];second.quiz.question='Which city hosts this demo event?';second.quiz.options=['Manchester','Bristol','London'];second.quiz.correct=0;
 return {version:1,events:[{id:'evt-midnight',code:'NIGHT26',name:'Midnight Festival',venue:'London · O2-inspired demo venue',date:'2026-11-14',status:'live',category:'Concert',state:first},{id:'evt-citybeats',code:'BEATS26',name:'City Beats Live',venue:'Manchester · Demo Arena',date:'2026-11-28',status:'live',category:'Music Festival',state:second}]};
}
function readDatabase(){let d;try{d=JSON.parse(localStorage.getItem(KEY)||'null')}catch(e){}if(!d||!Array.isArray(d.events)||!d.events.length||!d.events.every(x=>x.state?.poll&&x.state?.quiz))d=seededDatabase();for(const e of d.events)upgradeEvent(e);if(d.version!==2){if(!d.events.some(e=>e.code==='SUMMIT26'))d.events.push(makeSeedEvent('evt-summit','SUMMIT26','Harmoniq Business Summit','London · Corporate demo venue','2026-12-03','corporate'));if(!d.events.some(e=>e.code==='CAMPUS26'))d.events.push(makeSeedEvent('evt-campus','CAMPUS26','University Welcome Week','Bristol · Campus demo venue','2026-12-10','university'));d.version=2;try{localStorage.setItem(KEY,JSON.stringify(d))}catch(e){}}return d}
let db=readDatabase(),view=initialView,tab='overview',audiencePage='home',stageMode='welcome',editingEventId=null;
function findEvent(ref){return db.events.find(e=>e.id===ref||e.code===String(ref||'').toUpperCase())||null;}
let organiserEventId=sessionStorage.getItem('hm-organiser-event')||db.events[0].id;
let attendeeEventId=sessionStorage.getItem('hm-attendee-event')||null;
let displayEventId=QS.get('event')||sessionStorage.getItem('hm-display-event')||organiserEventId;
let joined=Boolean(attendeeEventId&&sessionStorage.getItem('hm-joined-current')===attendeeEventId);
let event=chooseEvent(),state=event.state;
function chooseEvent(){const id=view==='attendee'?(attendeeEventId||QS.get('event')||organiserEventId):view==='display'?displayEventId:organiserEventId;return findEvent(id)||db.events[0];}
function refreshActive(){event=chooseEvent();state=event.state;joined=Boolean(attendeeEventId&&sessionStorage.getItem('hm-joined-current')===attendeeEventId);}
const sessionId=(()=>{let id=sessionStorage.getItem('harmoniq-session-id');if(!id){id='d-'+Date.now().toString(36)+'-'+Math.floor(Math.random()*1e7).toString(36);sessionStorage.setItem('harmoniq-session-id',id)}return id})();
let bc;try{bc=new BroadcastChannel(CHANNEL);bc.onmessage=()=>refreshFromStorage()}catch(e){}
window.addEventListener('storage',e=>{if(e.key===KEY)refreshFromStorage()});
function refreshFromStorage(){db=readDatabase();refreshActive();draw()}
function updateDatabase(fn){const next=readDatabase();fn(next);db=next;try{localStorage.setItem(KEY,JSON.stringify(next))}catch(e){}try{bc?.postMessage({type:'changed'})}catch(e){}refreshActive();draw()}
function update(fn){const id=event.id;updateDatabase(d=>{const selected=d.events.find(e=>e.id===id);if(selected){fn(selected.state);selected.state.updated=Date.now();}})}
function selectOrganiser(id){if(!findEvent(id))return;organiserEventId=id;sessionStorage.setItem('hm-organiser-event',id);editingEventId=null;audiencePage='home';stageMode='welcome';refreshActive();draw();}
function selectDisplay(id){if(!findEvent(id))return;displayEventId=id;sessionStorage.setItem('hm-display-event',id);stageMode='welcome';refreshActive();draw();}
function joinEventByCode(code){const found=findEvent(String(code||'').trim().toUpperCase());if(!found){toast('Event not found. Check the code and try again.');return false;}
 if(found.status!=='live'){toast('This event is not open for attendees.');return false;}
 const previous=sessionStorage.getItem('hm-joined-current');
 updateDatabase(d=>{if(previous&&previous!==found.id){const old=d.events.find(e=>e.id===previous);if(old)old.state.attendees=Math.max(0,old.state.attendees-1)}if(previous!==found.id){const next=d.events.find(e=>e.id===found.id);if(next)next.state.attendees++;}});
 attendeeEventId=found.id;sessionStorage.setItem('hm-attendee-event',found.id);sessionStorage.setItem('hm-joined-current',found.id);
 audiencePage='home';view='attendee';refreshActive();draw();toast('Joined '+found.name+'!');return true;
}
function leaveEvent(){const prev=sessionStorage.getItem('hm-joined-current');if(prev)updateDatabase(d=>{const old=d.events.find(e=>e.id===prev);if(old)old.state.attendees=Math.max(0,old.state.attendees-1)});sessionStorage.removeItem('hm-joined-current');sessionStorage.removeItem('hm-attendee-event');attendeeEventId=null;joined=false;audiencePage='home';refreshActive();draw();}

function eventsManagement(){
 const list=db.events.map(e=>`<article class="event-card ${e.id===organiserEventId?'focused':''}"><div class="event-meta"><span class="event-status ${esc(e.status)}">${e.status.toUpperCase()}</span><span class="event-code">${esc(e.code)}</span><span class="type-chip">${esc(TYPES[categoryOf(e)].label)}</span></div><h3>${esc(e.name)}</h3><p>${esc(e.venue||'Location TBC')} · ${esc(e.date||'Date TBC')} · ${esc(e.visibility)}</p><div class="event-kpis">${e.state.attendees} demo participants · ${e.state.lightLaunchCount} light launches · ${e.state.pollLaunchCount} poll rounds</div><div class="event-actions"><button class="btn ${e.id===organiserEventId?'secondary':''}" data-select-event="${esc(e.id)}">${e.id===organiserEventId?'✓ Selected':'Manage event →'}</button><button class="btn ghost" data-edit-event="${esc(e.id)}">Edit</button><button class="btn ghost" data-toggle-event="${esc(e.id)}">${e.status==='live'?'Pause entry':'Open entry'}</button></div></article>`).join('');
 const e=db.events.find(e=>e.id===editingEventId);const c=e?categoryOf(e):'concert',modules=e?.modules||TYPES[c].modules;
 const categoryOptions=Object.entries(TYPES).map(([k,v])=>`<option value="${k}" ${c===k?'selected':''}>${esc(v.label)}</option>`).join('');
 const moduleChecks=Object.entries(MODULES).map(([key,label])=>`<label class="module-check"><input type="checkbox" data-event-module="${key}" ${modules.includes(key)?'checked':''} /><span>${esc(label)}</span></label>`).join('');
 return `${heading('ORGANISER / MULTI EVENT','Manage your events','Each event has an independent audience, activities, enabled modules, invite link and report.')}
 <div class="grid-3" style="margin-bottom:20px">${stat(db.events.length,'Events created','Stored in this browser')}${stat(db.events.filter(e=>e.status==='live').length,'Open for entry','Public and code-only')}${stat(db.events.reduce((a,e)=>a+e.state.attendees,0),'Demo attendees','Illustrative / local')}</div>
 <div class="panel"><h2>Event portfolio</h2><p class="descr">Switch among concert, corporate, university and pub event templates. Manage each event independently.</p><div class="event-list">${list}</div></div>
 <div class="panel"><h2>${e?'Edit event & modules':'Create a new event'}</h2><p class="descr">Select a use-case template, then enable only the experiences appropriate for that customer.</p>
 <div class="event-form"><div class="field"><label>Event name *</label><input class="input" id="manage-event-name" maxlength="80" placeholder="e.g. Innovation Day" value="${esc(e?.name||'')}"></div><div class="field"><label>Event access code *</label><input class="input" id="manage-event-code" maxlength="16" placeholder="e.g. INNOV26" value="${esc(e?.code||'')}"></div>
 <div class="field"><label>Event type / template</label><select class="input" id="manage-event-category">${categoryOptions}</select></div>
 <div class="field"><label>Visibility</label><select class="input" id="manage-event-visibility"><option value="public" ${!e||e.visibility!=='private'?'selected':''}>Public — listed for attendees</option><option value="private" ${e?.visibility==='private'?'selected':''}>Private — code or link only</option></select></div>
 <div class="field"><label>Venue / location</label><input class="input" id="manage-event-venue" maxlength="120" placeholder="e.g. London Innovation Centre" value="${esc(e?.venue||'')}"></div>
 <div class="field"><label>Event date</label><input class="input" id="manage-event-date" type="date" value="${esc(e?.date||'')}"></div>
 <div class="field span-2"><label>Entry status</label><select class="input" id="manage-event-status"><option value="live" ${(!e||e.status==='live')?'selected':''}>Open — attendee entry allowed</option><option value="draft" ${e?.status==='draft'?'selected':''}>Draft — entry closed</option><option value="closed" ${e?.status==='closed'?'selected':''}>Closed — event completed</option></select></div>
 <div class="field span-2"><label>Enabled modules</label><div class="check-grid" id="module-checkboxes">${moduleChecks}</div><p class="small muted">Audience navigation and organiser tools follow the modules selected here.</p></div>
 <div class="row span-2"><button class="btn" data-action="save-event">${e?'Save event changes':'Create event →'}</button>${e?'<button class="btn ghost" data-action="cancel-event-edit">Cancel editing</button>':''}</div></div></div>
 ${eventShareSection(event)}
 <div class="notice-warn">Demo mode: events and participant interactions are stored in this browser profile only. A GitHub Pages URL does not provide a shared cloud database or real cross-device synchronisation.</div>`;
}

function availableEventsForAudience(){return db.events.filter(e=>e.status==='live'&&e.visibility!=='private').map(e=>`<button class="event-lobby-card" data-join-code="${esc(e.code)}"><strong>${esc(e.name)}</strong><span>${esc(TYPES[categoryOf(e)].label)} · ${esc(e.venue||'Demo venue')} · CODE ${esc(e.code)} →</span></button>`).join('')||'<div class="mini-label">No public events are currently accepting attendees. Private events require a code or invite link.</div>'}
function eventOptions(selected){return db.events.map(e=>`<option value="${esc(e.id)}" ${e.id===selected?'selected':''}>${esc(e.name)} (${esc(e.code)})</option>`).join('')}

function esc(str){return String(str??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function toast(s){const n=document.getElementById('toast');n.textContent=s;n.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.classList.remove('show'),3000)}
function icon(name){const d={seating:'⌖',messaging:'✉',food:'🍽',events:'▦',overview:'◫',lights:'✦',poll:'◉',quiz:'★',announcements:'◈',sponsors:'◆',rewards:'◇',analytics:'▥',report:'▤',business:'£',future:'↗'};return d[name]||'•'}
function currentLight(){if(state.lightMode==='sequence'&&state.lightStarted){const seq=SEQUENCES[state.sequenceId]||SEQUENCES.aurora,t=(Date.now()-state.lightStarted)/1000;if(t>=seq.duration)return {color:state.color,label:'Sequence complete',done:true};let stage=seq.stages[0];for(const st of seq.stages)if(t>=st.at)stage=st;return {color:stage.color,label:stage.label,done:false}}if(state.lightMode==='solid')return {color:state.color,label:'Solid crowd colour',done:false};return {color:state.color,label:'Standby',done:false}}
function lightBanner(){let l=currentLight();return `<div class="lighting-stage" style="background:radial-gradient(ellipse at center,${l.color},#26173c 83%)"><div><span>${esc(l.label)}</span><strong>${state.lightMode==='sequence'&&!l.done?'AURORA WAVE':'LIGHT STUDIO'}</strong></div></div>`}
function qrMarkup(size=140){let squares='';let s=13;for(let y=0;y<s;y++)for(let x=0;x<s;x++){let corners=((x<4&&y<4)||(x>8&&y<4)||(x<4&&y>8));let on=corners?(x===0||x===3||y===0||y===3||(x===1&&y===1)||(x===10&&y===1)||(x===1&&y===10)):((x*13+y*17+x*y*7)%7<3);if(on)squares+=`<rect x="${x*8}" y="${y*8}" width="8" height="8" fill="#231b36"/>`;}return `<svg width="${size}" height="${size}" viewBox="0 0 104 104" aria-label="Decorative demo QR, not redeemable"><rect width="104" height="104" fill="white"/>${squares}</svg>`}
function statusPill(){return `<span class="pill live">● LIVE DEMO · ${state.attendees} connected</span>`}
function topbar(){return `<div class="topbar"><div class="topbar-brand"><div><div class="kicker">Harmoniq / Organiser</div><div class="crumb">${esc(event.name)} · Code ${esc(event.code)} · Interactive concept</div></div></div><div class="actions"><label class="event-switch-label">EVENT <select class="event-switch" id="organiser-event-switch">${eventOptions(organiserEventId)}</select></label>${statusPill()}<button class="btn ghost small-btn" data-action="open-audience">↗ Audience</button><button class="btn ghost small-btn" data-action="open-display">▣ Display</button><button class="btn secondary small-btn" data-action="open-hub">Explore</button><button class="btn ghost small-btn" data-action="reset-demo" title="Reset the currently selected event only">Reset event</button></div></div>`}
function sidebar(){let sections=[['EVENTS',['events']],['CONTROL',['overview','lights','poll','quiz','announcements','seating']],['COMMERCIAL',['food','sponsors','rewards','analytics','report']],['ROADMAP',['future','business']]];let names={seating:'Seats & zones',food:'Food operations',events:'All events',overview:'Overview',lights:'Light control',poll:'Live polls',quiz:'Quiz & trivia',announcements:'Announcements',sponsors:'Sponsor moments',rewards:'Rewards & offers',analytics:'Analytics',report:'Event report',future:'Future features',business:'Business model'};return `<aside class="sidebar"><div class="brand"><span class="logo-mark">✦</span>HARMONIQ</div>${sections.map(([name,ls])=>`<div class="nav-label">${name}</div><div class="nav-group">${ls.map(k=>`<button class="nav-btn ${tab===k?'active':''} ${MODULES[k]&&!enabledFor(event,k)?'module-off':''}" data-tab="${k}" ${MODULES[k]&&!enabledFor(event,k)?'title="Enable this module in Event settings"':''}><span style="font-size:20px;width:20px">${icon(k)}</span>${names[k]||k}${MODULES[k]&&!enabledFor(event,k)?' · off':''}</button>`).join('')}</div>`).join('')}<div class="sidebar-foot"><span class="badge">PRE-MVP · UK / B2B</span><p>Demonstration data is browser-local. No real customer accounts, billing or device sync.</p></div></aside>`}
function heading(k,t,sub){return `<div class="kicker">${k}</div><h1 class="hero-title">${t}</h1><p class="lead">${sub}</p>`}
function stat(v,label,sub){return `<div class="stat"><strong>${esc(v)}</strong><span>${esc(label)}</span><em>${esc(sub)}</em></div>`}
function organizerContent(){if(tab==='messaging')tab='announcements';if(tab==='events')return eventsManagement();if(['seating','food'].includes(tab)){if(!enabledFor(event,tab))return heading('MODULE DISABLED','Module not enabled','Enable this service in All Events → Edit.');return tab==='seating'?seatAdmin():foodAdmin();}if(MODULES[tab]&&!enabledFor(event,tab))return `${heading('MODULE DISABLED','Module not enabled',`The ${esc(MODULES[tab])} module is not active for ${esc(event.name)}.`)}<div class="panel"><p class="descr">Open All events → Edit, enable this module and save the event to continue.</p><button class="btn" data-tab="events">Manage event modules →</button></div>`;if(tab==='overview')return `${heading('EVENT CONTROL ROOM / '+esc(TYPES[categoryOf(event)].label),'Run an experience for '+esc(event.name), 'One control centre with modules tailored to this event type.')}
 <div class="grid-3" style="margin-bottom:22px">${stat(state.attendees,'Demo attendees','Illustrative/local count')}${stat(totalVotes(),'Current poll votes','Recorded in browser')}${stat(state.lightLaunchCount,'Light launches','Recorded in browser')}</div>
 <div class="panel"><h2>Available modules for this event</h2><p class="descr">The attendee interface hides disabled features. Configure modules from All events → Edit.</p><div class="module-grid">${[['lights','✦','Light experience','Time-based colours and sequences'],['poll','◉','Live polling','Multiple choice or Yes / No'],['quiz','★','Quiz & trivia','Simple scoring and results'],['announcements','◈','Announcements','Non-emergency notices'],['sponsors','◆','Sponsor moment','Configurable demo campaigns'],['analytics','▥','Engagement insights','Per-event demo metrics']].filter(x=>enabledFor(event,x[0])).map(([k,i,t,d])=>`<button class="module" data-tab="${k}"><div class="module-icon">${i}</div><b>${t}</b><p>${d}</p><span>Open module →</span></button>`).join('')}</div></div><div class="panel"><div class="row"><button class="btn secondary" data-tab="report">View event report</button><button class="btn ghost" data-tab="seating">Seat check-in</button><button class="btn ghost" data-tab="food">Food operations</button><button class="btn ghost" data-tab="events">Event details & QR</button></div></div>`;
 if(tab==='lights')return `${heading('ENGAGE / LIGHTING','Light experience','Choose solid colour or one of two preloaded timed sequences. Real device synchronisation remains untested.')}${lightBanner()}<div class="panel"><h2>Set a crowd colour</h2><div class="color-list">${Object.entries(COLORS).map(([key,color])=>`<button title="${key}" aria-label="Select ${key}" class="swatch ${state.color===color?'selected':''}" data-color="${key}" style="background:${color}"></button>`).join('')}</div><div class="row"><button class="btn" data-action="activate-solid">Apply selected colour</button><button class="btn ghost" data-action="stop-light">Stop lighting</button></div></div><div class="panel"><h2>Preloaded timed sequences</h2><p class="descr">Sequences use a shared clock in browser tabs. The pilot must validate synchronisation on 10–30 physical devices.</p>${Object.entries(SEQUENCES).map(([key,seq])=>`<div class="scene-row"><div><strong>✦ ${esc(seq.name)}</strong><p>${seq.stages.map(t=>t.label).join(' → ')} · ${seq.duration}s</p></div><button class="btn" data-sequence="${key}">▶ Launch</button></div>`).join('')}<p class="tooltip">Opt-in and device compatibility are essential before any public light-show pilot.</p></div>`;
 if(tab==='poll')return `${heading('ENGAGE / POLLING','Poll manager','Prepare a question queue, launch one at a time, and view per-event responses.')}
 <div class="panel"><h2>Question library <span class="badge">${state.pollBank.length} prepared</span></h2><p class="descr">Three preset questions for this event type. Select any question to launch a new round.</p>${state.pollBank.map((p,i)=>`<div class="scene-row"><div><strong>${i+1}. ${esc(p.question)}</strong><p>${p.type==='yesno'?'Yes / No':'Multiple choice'} · ${p.options.length} answers</p></div><button class="btn secondary small-btn" data-run-question="${i}">Launch →</button></div>`).join('')}</div>
 <div class="panel"><h2>Create another question</h2><div class="field"><label>Question type</label><select class="input" id="poll-type"><option value="choice">Multiple choice (3 options)</option><option value="yesno">Yes / No</option></select></div><div class="field"><label>Question</label><input id="poll-question" class="input" maxlength="125" placeholder="What would you like to ask?"></div><div id="poll-option-fields" class="option-editor">${['Option A','Option B','Option C'].map((l,i)=>`<div class="field"><label>${l}</label><input class="input" id="poll-option-${i}" placeholder="${l}" maxlength="56"></div>`).join('')}</div><button class="btn" data-action="add-poll-question">Add to question library</button></div>
 <div class="panel"><h2>Current poll <span class="badge">${state.poll.open?'LIVE':'CLOSED'}</span></h2><h3>${esc(state.poll.question)}</h3>${pollBars()}<p class="small muted">${totalVotes()} demo votes · Poll round ${state.poll.version}</p><button class="btn ghost" data-action="close-poll">Close current poll</button></div>`;
if(tab==='quiz')return `${heading('ENGAGEMENT / TRIVIA','Quiz & trivia','A simple live quiz with attendee feedback and demonstration scoring.')}<div class="panel"><div class="kicker">ROUND 01 / 03</div><h2 style="font-size:25px;margin-top:13px">${esc(state.quiz.question)}</h2>${state.quiz.options.map((o,i)=>`<div class="scene-row"><strong>${String.fromCharCode(65+i)}. ${esc(o)}</strong>${i===state.quiz.correct?'<span class="badge">Correct answer</span>':''}</div>`).join('')}<div class="row" style="margin-top:24px"><button class="btn" data-action="launch-quiz">Start trivia round →</button><button class="btn ghost" data-action="close-quiz">Close round</button></div><p class="tooltip">Participants can answer once per round in their browser session.</p></div>`;
if(tab==='announcements')return `${heading('COMMUNICATE / ANNOUNCEMENTS','Announcements','Send one message to all event attendees or only to a selected seating zone. Non-emergency messages only.')}
<div class="panel"><h2>Compose announcement</h2>
 <div class="field"><label>Recipients</label><select class="input" id="announcement-target">${zoneOption()}</select><p class="small muted">All zones = everyone in this event. A named zone = attendees who confirmed a seat there. ${enabledFor(event,'seating')?'':'Seat & zone check-in must be enabled for zone targeting.'}</p></div>
 <div class="field"><label>Message</label><textarea class="input" id="announcement-body" maxlength="260" placeholder="Write an update for your selected audience..."></textarea></div>
 <div class="row"><button class="btn" data-action="send-announcement">Send announcement →</button><button class="btn ghost" data-action="clear-announcement">Clear active banners</button></div>
 <p class="small muted" style="margin-top:15px">Messages are saved per event in this browser. They appear in the attendee Updates screen and as a home-screen banner only for the selected audience. Not a push notification.</p></div>
<div class="panel"><h2>Announcements history · ${state.messages.length}</h2>
${state.messages.length?state.messages.slice().reverse().map(m=>`<div class="scene-row"><div><span class="microtag">${esc(m.zone==='all'?'ALL ATTENDEES':'ZONE '+m.zone)}</span><span class="small muted" style="margin-left:9px">${esc(new Date(m.date).toLocaleString('en-GB'))}</span><p>${esc(m.text)}</p></div><span class="small muted">${m.active===false?'Archived':'Active'}</span></div>`).join(''):'<p class="small muted">No announcements have been sent yet.</p>'}</div>`;
 if(tab==='sponsors')return `${heading('ACTIVATE / CAMPAIGN','Sponsor moments','Create a per-event sponsor takeover with a limited demo offer.')}
 <div class="panel"><h2>Event sponsor campaign</h2><p class="descr">All partner information is illustrative, not a commercial agreement.</p><div class="field"><label>Partner name</label><input id="sponsor-name" class="input" maxlength="60" value="${esc(state.sponsor.name)}"></div><div class="field"><label>Campaign headline</label><input id="sponsor-headline" class="input" maxlength="90" value="${esc(state.sponsor.headline)}"></div><div class="field"><label>Offer description</label><input id="sponsor-offer" class="input" maxlength="100" value="${esc(state.sponsor.offer)}"></div><div class="event-form"><div class="field"><label>Redemption limit</label><input id="sponsor-limit" class="input" type="number" min="1" max="999" value="${state.sponsor.limit}"></div><div class="field"><label>Offer expiry (optional)</label><input id="sponsor-expiry" class="input" type="date" value="${esc(state.sponsor.expiry||'')}"></div></div><div class="row"><button class="btn secondary" data-action="save-sponsor">Save campaign</button><button class="btn" data-action="launch-sponsor">Activate sponsor moment →</button><button class="btn ghost" data-action="close-sponsor">End moment</button></div></div><div class="panel">${sponsorMobile()}<p class="small muted">Demo partner only · no payment or POS integration</p></div>`;
 if(tab==='rewards')return `${heading('ACTIVATE / REWARDS','Offer redemption','Generate a demo claim code and validate it at the venue desk. No POS integration.')}
 <div class="grid-3" style="margin-bottom:20px">${stat(state.claims.length,'Offer claims','Recorded in this browser')}${stat(state.claims.filter(c=>c.used).length,'Valid redemptions','Manually checked by staff')}${stat(state.sponsor.limit,'Maximum redemptions','Campaign-defined limit')}</div><div class="panel"><h2>Validate an attendee code</h2><div class="field"><label>Claim code</label><input class="input mono" id="redeem-code" placeholder="e.g. HM-AB1234" autocomplete="off"></div><button class="btn" data-action="redeem-offer">Validate & redeem</button><p class="descr" style="margin-top:12px">This is a simulated desk check. Codes are saved per event and cannot be redeemed twice.</p></div><div class="panel"><h2>Recent claims</h2>${state.claims.length?state.claims.slice(-10).reverse().map(c=>`<div class="scene-row"><strong class="mono">${esc(c.code)}</strong><span class="type-chip">${c.used?'Redeemed':'Unredeemed'}</span></div>`).join(''):'<div class="mini-empty">No claims yet. Open the attendee offer screen to create one.</div>'}</div>`;
 if(tab==='analytics')return `${heading('INSIGHTS / PILOT','Basic analytics','Track interactions for the selected event. Values recorded locally are not real multi-device telemetry.')}
 <div class="grid-3" style="margin-bottom:20px">${stat(state.attendees,'Demo attendees','Baseline may be illustrative')}${stat(totalVotes(),'Current poll responses','Locally recorded')}${stat(state.claims.filter(c=>c.used).length,'Offer redemptions','Verified in this demo')}</div><div class="panel"><h2>Active poll breakdown</h2>${pollBars()}</div><div class="panel"><h2>Interactions captured in this browser</h2><div class="report-metrics">${Object.entries({['Poll rounds']:state.pollLaunchCount,['Quiz answers']:state.quizResponses,['Light launches']:state.lightLaunchCount,['Announcements sent']:state.messagesSent,['Feedback forms']:state.feedback.length,['QR offers claimed']:state.claims.length}).map(([k,v])=>`<div><b>${v}</b><span>${k}</span></div>`).join('')}</div><p class="small muted">Latency, device failure rate and network resilience require actual multi-device testing.</p><button class="btn secondary" data-tab="report">View post-event report →</button></div>`;
 if(tab==='report'){const r=selectedReport(event);return `${heading('REPORTING / POST EVENT','Event report', 'A per-event summary based on stored prototype actions, with explicit demo limitations.')}
 <div class="panel"><h2>${esc(event.name)} · ${esc(event.code)}</h2><p class="descr">${esc(TYPES[categoryOf(event)].label)} · ${esc(event.venue)} · ${esc(event.date||'Date TBC')}</p><div class="report-metrics">${Object.entries({'Demo attendees':r.attendees,'All poll votes':r.votes,'Quiz responses':r.answered,'Light launches':r.lightShows,'Announcements':r.announcements,'Offer claims':r.claims,'Redeemed offers':r.redeemed,'Feedback count':r.feedback,'Mean satisfaction':r.avgRating,'Seat check-ins':r.seatCheckins,'Zone messages':r.zoneMessages,'Demo food orders':r.foodOrders,'Seat deliveries':r.foodDelivery}).map(([k,v])=>`<div><b>${v}</b><span>${k}</span></div>`).join('')}</div><p class="small muted" style="margin-top:17px">Attendee figures can include a seeded illustrative baseline. All other actions here are local demo interactions. No customer conversion, network delay or cross-device KPIs are asserted.</p><div class="row"><button class="btn" data-action="export-event-report">Export CSV report</button><button class="btn ghost" data-tab="events">Return to events</button></div></div>`}
 if(tab==='guide-preview')return `${heading('GUIDE / PHASE 2 PREVIEW','Venue guidance concept','A future floor-plan service requiring verified venue data.')}
<div class="panel"><div class="kicker">FUTURE / NOT AN ACTIVE MAP</div><h2>Find your zone & seat</h2><div style="background:repeating-linear-gradient(55deg,#342a49 0,#342a49 43px,#46345d 44px,#46345d 47px);height:280px;border-radius:18px;display:grid;place-items:center"><span class="pill">ZONE A1 · DEMO ONLY</span></div><p class="descr" style="margin-top:17px">Seat guidance, accessibility routes and facilities need the venue's authoritative map. Not available for the current MVP.</p><button class="btn secondary" data-tab="future">Back to roadmap</button></div>`;
if(tab==='food-preview')return `${heading('AI DISCOVER & DINE / PHASE 3 PREVIEW','Food discovery concept','A future module, not an AI recommender or ordering system.')}
<div class="panel"><h2>Explore food by preferences</h2><p class="descr">Example user request: spicy food, up to £15, low calorie, and peanut-free. These are conceptual filters only.</p><div class="field"><label>Budget (example)</label><input class="input" value="Up to £15" readonly></div><div class="field"><label>Food preferences (example)</label><input class="input" value="Spicy · Low calorie" readonly></div><div class="field"><label>Allergen information</label><input class="input" value="Requires vendor-verified allergen data" readonly></div><div class="notice-warn">No food items can be labelled safe or recommended without verified supplier menus, nutritional and allergen records. No order or payment functionality exists.</div><button class="btn secondary" style="margin-top:18px" data-tab="future">Back to roadmap</button></div>`;
if(tab==='business')return `${heading('B2B / BUSINESS MODEL','Commercial model preview','Illustrative packaging only. Prices and sales assumptions require UK market validation.')}
 <div class="futures">${[['Per-event licence','Single-event access and support; usage depends on the organiser'],['Organiser subscription','Repeated events under a shared organisation account'],['Sponsor activation','Optional limited campaigns and aggregate reporting']].map(([n,d])=>`<div class="future"><span class="tag">BUSINESS HYPOTHESIS</span><b>${n}</b><p>${d}</p></div>`).join('')}</div><div class="notice-warn" style="margin-top:18px">No payment processing, customer contracts, verified pricing or revenue have been implemented in this demo.</div>`;
 return `${heading('ROADMAP / CONCEPT','Future platform modules','Concept previews only; these are outside the initial MVP.')}
 <div class="futures">${[['GUIDE / Venue guidance','Zone and seat directions from verified venue data','Phase 2'],['COMMUNICATE / Zone messaging','Zone messages are a demo module; server delivery and operator authorisation remain Phase 2','Limited demo'],['AI DISCOVER & DINE','Find food using verified menus, budget and disclosed dietary information','Phase 3'],['Future sponsor reporting','Expanded campaign insights beyond basic pilot metrics','Later'],['Smart modular displays','Hardware-connected experiences after integration tests','Later']].map(([a,b,c])=>`<div class="future preview"><span class="tag">${c.toUpperCase()} / PREVIEW</span><b style="margin-top:15px">${a}</b><p>${b}</p>${a.includes('AI DISCOVER')?'<p class="small muted">Not a real AI recommendation. Allergy safety requires vendor-verified data.</p><button class="btn secondary small-btn" data-tab="food-preview">View concept →</button>':a.includes('Venue guidance')?'<button class="btn secondary small-btn" data-tab="guide-preview">View concept →</button>':''}</div>`).join('')}</div><div class="notice-warn" style="margin-top:15px">Emergency evacuation and life-safety systems are out of scope. Harmoniq is not a replacement for authorised venue safety infrastructure.</div>`;
}
function totalVotes(){return state.poll.votes.reduce((a,b)=>a+b,0)}
function pollBars(){let sum=totalVotes();return state.poll.options.map((name,i)=>{const pct=sum?Math.round(state.poll.votes[i]/sum*100):0;return `<div class="result-item"><div class="result-head"><strong>${esc(name)}</strong><strong>${pct}%</strong></div><div class="bar-bg"><div class="bar-fill" style="width:${pct}%"></div></div></div>`}).join('')}
function sponsorMobile(){return `<div class="sponsor-panel"><div style="font-size:11px;color:#ffd4f3;letter-spacing:2px">DEMO PARTNER MOMENT</div><b>${esc(state.sponsor.name)}</b><span>${esc(state.sponsor.headline)}</span><p style="color:#fff">${esc(state.sponsor.offer)}</p></div><button class="btn phone-action" data-mobile="reward">View limited offer →</button>`}
function phoneHtml(compact=true){if(!compact&&!joined){const pre=QS.get('event');const preset=findEvent(pre)?.code||'NIGHT26';return `<div class="phone"><div class="phone-main"><div class="phone-header">HARMONIQ <span class="live-dot">●</span></div><div class="kicker">JOIN YOUR EVENT · UK PRE-MVP</div><h2>Find your moment.</h2><p>Join via event code or QR invite. No account needed for this concept demo.</p><div class="field"><label>Enter event code</label><input class="input" id="event-code" value="${esc(preset)}" maxlength="16" /></div><button class="btn phone-action" data-action="join-event">Join event →</button><div class="event-lobby"><div class="eyebrow">PUBLIC EVENTS</div>${availableEventsForAudience()}</div><p class="small muted">Private events are accessed using a code/link only. All stored activity stays in this browser.</p></div></div>`;}
const back=`<button class="phone-back" data-mobile="home">← Back to event</button>`;let content='';let footer=true;
 if(audiencePage==='home'){let tiles=[['lights','✦','Light show','Join the colours'],['poll','◉','Live poll','Make your choice'],['quiz','★','Trivia','Play & score'],['sponsor','◆','Sponsor','Explore the partner'],['announcement','◈','Updates','Organiser messages'],['reward','◇','Offers','Claim a reward'],['feedback','♡','Feedback','Rate the experience']];tiles=tiles.filter(x=>enabledFor(event,({sponsor:'sponsors',announcement:'announcements',reward:'rewards',feedback:'analytics'})[x[0]]||x[0]));content=`<div class="phone-header">HARMONIQ <span class="live-dot">● ACTIVE</span></div><div class="eyebrow">${esc(event.name.toUpperCase())} · ${esc(TYPES[categoryOf(event)].label)}</div><h2>Welcome to your event.</h2><p>Only the modules selected by your organiser appear here.</p>${enabledFor(event,'announcements')&&latestAudienceMessage()?`<button class="phone-banner" data-mobile="announcement" style="text-align:left;width:100%;color:white;border:1px solid #986bd6">📣 ${esc(latestAudienceMessage().zone==='all'?'All attendees':'Zone '+latestAudienceMessage().zone)}: ${esc(latestAudienceMessage().text)}</button>`:''}${state.sponsorActive&&enabledFor(event,'sponsors')?`<button class="phone-banner" data-mobile="sponsor" style="text-align:left;width:100%;color:white;border:1px solid #5e447c">★ A partner moment is live — explore →</button>`:''}<div class="festival-card"><span>● EVENT CONNECTED · DEMO</span><b>${esc(event.name.toUpperCase())}</b><p>${state.attendees} demo attendees · Code ${esc(event.code)}</p></div><div class="phone-tile-grid">${tiles.map(([key,i,name,sub])=>`<button class="phone-tile" data-mobile="${key}">${i}<b>${name}</b><span>${sub}</span></button>`).join('')}</div><div class="event-mini-row" style="margin-top:13px"><span class="mini-label">CODE ${esc(event.code)}</span><button data-action="leave-event">↔ Switch event</button></div>`}
 if(audiencePage==='lights'){const l=currentLight();if(state.lightMode!=='idle'&&!l.done){footer=false;content=`<div class="light-full" style="background:${l.color}"><div class="light-brand">HARMONIQ · OPT-IN LIGHT</div><div style="text-align:center"><strong>${state.lightMode==='sequence'?esc(SEQUENCES[state.sequenceId]?.name||'Light Sequence'):'CROWD COLOUR'}</strong><p>${esc(l.label)}</p></div><button class="btn secondary" data-mobile="home">Exit light mode ×</button></div>`}else content=`${back}<div class="eyebrow">ENGAGE / LIGHT EXPERIENCE</div><h2>Light up the crowd.</h2><p>Choose to participate in the organiser's colour experience. Keep the screen open.</p><div class="lighting-stage" style="height:235px;margin-top:30px"><div><span>STANDBY</span><strong>READY</strong></div></div><div class="notice-warn">Opt-in visual effect demo. No flashing, emergency function or guaranteed multi-device sync is provided.</div>`}
 if(audiencePage==='poll'){let already=sessionStorage.getItem('harmoniq-vote-'+event.id+'-'+state.poll.version)==='1';content=`${back}<div class="eyebrow">ENGAGE / LIVE POLL ${state.poll.open?'● OPEN':'· PREVIEW'}</div><h2>${esc(state.poll.question)}</h2><p>Choose one answer to take part in this event.</p>${already?`<div class="phone-result">✓ Vote submitted</div>${pollBars()}`:state.poll.open?state.poll.options.map((opt,i)=>`<button class="option" data-vote="${i}">${String.fromCharCode(65+i)} &nbsp; ${esc(opt)} →</button>`).join(''):'<div class="notice">The organiser has not launched this question yet.</div>'}<div class="mini-label">${state.poll.open?'Demo results are browser-local and not shared across independent devices.':'Wait for the organiser to launch a question.'}</div>`}
 if(audiencePage==='quiz'){let selection=sessionStorage.getItem('harmoniq-quiz-'+event.id+'-'+state.quiz.version);content=`${back}<div class="eyebrow">ENGAGE / QUIZ</div><h2>${esc(state.quiz.question)}</h2><p>Choose one answer to earn 100 demonstration points.</p>${selection!==null?`<div class="score">${Number(selection)===state.quiz.correct?'+100':'0'}</div><p style="text-align:center">${Number(selection)===state.quiz.correct?'Correct! Nice one.':'Great try. Correct answer: '+esc(state.quiz.options[state.quiz.correct])+'.'}</p>`:state.quiz.open?state.quiz.options.map((opt,i)=>`<button class="option" data-quiz="${i}">${String.fromCharCode(65+i)} &nbsp; ${esc(opt)} →</button>`).join(''):'<div class="notice">Quiz starts when the organiser launches the round.</div>'}` }
if(audiencePage==='announcement')content=`${back}<div class="eyebrow">OFFICIAL UPDATES</div><h2>Announcements</h2><p>Updates for all attendees and for your confirmed seat zone.</p>${visibleAudienceMessages().length?visibleAudienceMessages().slice().reverse().map(m=>`<div class="phone-banner" style="font-size:14px;margin-top:15px;padding:17px"><b>${esc(m.zone==='all'?'All attendees':'📍 '+m.zone+' zone')}</b><div class="small muted" style="margin-top:7px">${esc(new Date(m.date).toLocaleString('en-GB'))}</div><p style="color:inherit;margin-bottom:0">${esc(m.text)}</p></div>`).join(''):'<div class="notice" style="margin-top:24px">No announcements for your event or zone yet.</div>'}<p class="small muted">Messages are shown from this browser demo. Emergency alerts are not supported.</p>`;
if(audiencePage==='sponsor')content=`${back}<div class="eyebrow">SPONSOR EXPERIENCE</div><h2>A moment powered by a partner.</h2>${sponsorMobile()}`;
 if(audiencePage==='reward'){const my=state.claims.find(c=>c.session===sessionId),allowed=state.sponsorActive&&state.claims.filter(c=>c.used).length<state.sponsor.limit&&(!state.sponsor.expiry||state.sponsor.expiry>=new Date().toISOString().slice(0,10));content=`${back}<div class="eyebrow">ACTIVATE / OFFER</div><h2>Your event reward.</h2><div style="background:#f6f2ff;color:#2e2444;border-radius:22px;padding:17px;margin-top:19px;text-align:center"><strong>${esc(state.sponsor.name)}</strong><div class="reward-qr">${my?realQR('HARMONIQ DEMO '+event.code+' '+my.code,128):realQR(shareUrl(event),128)}</div><b>${esc(state.sponsor.offer)}</b><p style="color:#665d73">${my?'DEMO CLAIM: '+esc(my.code):'Demonstration offer · no payment or POS'}</p></div>${my?`<div class="notice ${my.used?'green':''}">${my.used?'✓ This code was validated at the demo desk.':'Show your claim code to the venue operator for demo validation.'}</div>`:allowed?'<button class="btn phone-action" data-action="claim-offer">Claim demo reward</button>':'<div class="notice-warn">This campaign has expired or reached its redemption limit.</div>'}<button class="btn secondary phone-action" data-mobile="home">Return to event →</button>`}
 if(audiencePage==='feedback'){let prior=(state.feedback||[]).some(f=>f.session===sessionId);content=`${back}<div class="eyebrow">PILOT / FEEDBACK</div><h2>How was the experience?</h2><p>Your quick optional rating helps organisers understand the event. No name is requested.</p>${prior?'<div class="notice green">✓ Your feedback has been recorded in this browser.</div>':`<div class="feedback-row">${[1,2,3,4,5].map(i=>`<button aria-label="Rate ${i} out of 5" data-feedback="${i}">${i}★</button>`).join('')}</div>`}<p class="small muted">Demo ratings only; not a verified pilot survey.</p>`}
 if(audiencePage==='food'){content=`${back}<div class="eyebrow">FUTURE / PHASE 3 ONLY</div><h2>AI Discover & Dine</h2><p>Concept only: explore food by budget and preferences using vendor-verified menu data.</p><div class="notice-warn">This preview does not make actual food recommendations or allergy-safety claims. It requires verified vendor data and separate validation.</div>`}
if(audiencePage==='map')content=`${back}<div class="eyebrow">FUTURE CONCEPT</div><h2>Venue guidance.</h2><p>Zone-based maps and seat finding are planned for future versions.</p><div style="padding:30px;background:repeating-linear-gradient(45deg,#251e3b 0,#251e3b 27px,#302646 28px,#302646 30px);border:1px solid #574571;border-radius:20px;margin-top:35px;text-align:center;height:250px;display:grid;place-items:center"><div class="badge">ZONE A1 · PREVIEW ONLY</div></div>`;
 const footerNav=[['home','Home'],['lights','Lights'],['poll','Poll'],['reward','Offers']].filter(([key])=>key==='home'||enabledFor(event,key==='reward'?'rewards':key));return `<div class="phone ${!footer?'full-light':''}"><div class="phone-main">${content}</div>${footer?`<div class="phone-footer">${footerNav.map(([k,name])=>`<button class="${audiencePage===k?'selected':''}" data-mobile="${k}">${name}</button>`).join('')}</div>`:''}</div>`}
function studio(){return `<div class="debug-banner">HARMONIQ V4 · UNIFIED ANNOUNCEMENTS / SEAT / FOOD · BROWSER-LOCAL DEMO · NOT PRODUCTION SOFTWARE</div><div class="shell">${sidebar()}<main class="main">${topbar()}<div class="layout"><section class="workspace">${organizerContent()}</section><aside class="preview-column"><div class="preview-cap"><div><div class="kicker">LIVE AUDIENCE PREVIEW</div><p class="small muted" style="margin:8px 0 0">Phone screen mirrored in-browser</p></div><button class="btn ghost small-btn" data-action="open-audience">↗</button></div>${phoneHtml()}</aside></div></main></div>`}
function attendee(){return `<div class="debug-banner">HARMONIQ ATTENDEE DEMO · MULTI-EVENT ACCESS</div><div style="min-height:100vh;display:grid;place-items:center;padding:30px;background:radial-gradient(circle at 50% 10%,#34224f,#0b0919 65%)"><div style="position:fixed;top:25px;left:30px"><button class="btn ghost small-btn" data-action="open-hub">← Explore product</button></div>${phoneHtml(false)}</div>`}
function display(){const l=currentLight();let body='';if(state.sponsorActive&&enabledFor(event,'sponsors')){body=`<div class="display-sponsor"><div class="kicker" style="color:#ffd9f4">DEMO SPONSOR MOMENT</div><h1>${esc(state.sponsor.name)}</h1><h2 class="sub">${esc(state.sponsor.headline)}</h2><p style="color:white">${esc(state.sponsor.offer)}</p></div>`}else if(state.lightMode!=='idle'&&!l.done&&enabledFor(event,'lights')){body=`<div class="display-light" style="background:${l.color}"><strong>${esc(state.lightMode==='solid'?'CROWD COLOUR':SEQUENCES[state.sequenceId]?.name||'Timed scene')}</strong></div><p>Optional shared light moment · Demonstration</p>`}else if((stageMode==='poll'||state.poll.open)&&enabledFor(event,'poll')){body=`<h1>${esc(state.poll.question)}</h1><div class="display-poll">${pollBars()}</div><p>${totalVotes()} browser-demo votes for ${esc(event.name)}</p>`}else if(stageMode==='quiz'&&enabledFor(event,'quiz')){body=`<div class="kicker">LIVE TRIVIA</div><h1>${esc(state.quiz.question)}</h1><p>Answer on your phone · ${state.quizResponses} demo responses</p>`}else if(state.announcementSent&&enabledFor(event,'announcements')){body=`<h1>MESSAGE FROM THE ORGANISER</h1><p style="color:white;font-size:38px;max-width:980px">${esc(state.announcement)}</p>`}else{body=`<div class="kicker">WELCOME / ${esc(TYPES[categoryOf(event)].label)}</div><h1>YOUR EVENT.<br/>YOUR MOMENT.</h1><p>Join using code <strong style="color:white">${esc(event.code)}</strong></p><div style="display:flex;gap:16px;margin-top:38px;align-items:center"><div class="qr-real">${realQR(shareUrl(event),133)}</div><div><p>Scan this QR with your phone to open the attendee page.</p><p class="small muted">Devices have independent browser data; this does not provide live cross-device control.</p></div></div>`}return `<div class="display-screen"><div class="display-header"><div class="brand"><span class="logo-mark">✦</span>HARMONIQ <span class="kicker" style="font-size:12px;margin-left:10px">LIVE DISPLAY · ${esc(event.name.toUpperCase())}</span></div><div class="actions"><label class="event-switch-label">EVENT <select id="display-event-switch" class="event-switch">${eventOptions(displayEventId)}</select></label><span class="pill live">DEMO · ${state.attendees} shown</span><button class="btn ghost small-btn" data-action="set-display-poll">Poll</button><button class="btn ghost small-btn" data-action="set-display-quiz">Quiz</button><button class="btn secondary small-btn" data-action="open-hub">Explore</button><button class="btn ghost small-btn" data-action="fullscreen">⛶</button></div></div><div class="display-stage">${body}</div><p style="position:fixed;bottom:17px;right:24px;font-size:11px;color:#716984">HARMONIQ · CONCEPT, NOT LIVE EVENT SOFTWARE</p></div>`}
function hub(){return `<div class="landing"><div class="brand"><span class="logo-mark">✦</span>HARMONIQ</div><div class="kicker" style="margin-top:16px">MODULAR EVENT EXPERIENCE · UK B2B PRE-MVP · OCTOBER 2026</div><h1>One platform.<br/><i>Many moments.</i></h1><p class="landing-sub">Configure events, let guests check in at seats, send zone messages, run opt-in lighting and explore demo restaurant ordering with pickup or seat delivery — all in one concept workspace.</p><div class="landing-grid">${[['01','Organiser workspace','Create a conference, university activity, pub quiz or concert. Configure modules and share a QR.','studio'],['02','Attendee experience','Join one of several events and access only its active experiences.','attendee'],['03','Live venue display','Present polls, messages, sponsor moments and timed colour scenes.','display']].map(([n,title,sub,v])=>`<button class="landing-card" data-view="${v}"><div class="kicker">${n} / EXPLORE</div><b>${title}</b><p>${sub}</p><em>Open experience →</em></button>`).join('')}</div><div class="notice" style="max-width:930px">V3 CONCEPT PROTOTYPE · Seat/food orders and local messages are simulations only. No real order/payment/restaurant service. Browser-local simulation, not a networked pilot. The 10–30 device synchronisation target and 30–100 participant pilot require a backend, permission controls and device testing.</div></div>`}
function draw(){refreshActive();const a=document.getElementById('app');a.innerHTML=view==='studio'?studio():view==='attendee'?attendee():view==='display'?display():hub();document.title='Harmoniq — '+({studio:'Organiser Control Room',attendee:'Attendee Experience',display:'Live Display',hub:'Product Demo'})[view]}
function nav(v){view=v;if(v==='attendee')joined=Boolean(attendeeEventId&&sessionStorage.getItem('hm-joined-current')===attendeeEventId);draw();try{history.replaceState(null,'',location.pathname+'?view='+encodeURIComponent(v))}catch(e){}window.scrollTo(0,0)}
function enterMobile(s){audiencePage=s;draw()}
function openView(v){window.open(location.pathname+'?view='+v+'&event='+encodeURIComponent(event.code),'_blank','noopener,noreferrer')}
function downloadContent(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function handleAction(action){switch(action){
case'open-hub':nav('hub');break;
case'open-audience':openView('attendee');break;
case'open-display':openView('display');break;
case'join-event':joinEventByCode(document.getElementById('event-code')?.value);break;
case'leave-event':leaveEvent();break;
case'cancel-event-edit':editingEventId=null;draw();break;
case'save-event':{
 const name=document.getElementById('manage-event-name')?.value.trim();
 const code=document.getElementById('manage-event-code')?.value.trim().toUpperCase();
 const venue=document.getElementById('manage-event-venue')?.value.trim()||'';
 const date=document.getElementById('manage-event-date')?.value||'';
 const status=document.getElementById('manage-event-status')?.value||'live';
 const category=document.getElementById('manage-event-category')?.value||'concert';
 const visibility=document.getElementById('manage-event-visibility')?.value||'public';
 const modules=[...document.querySelectorAll('[data-event-module]:checked')].map(n=>n.dataset.eventModule);
 if(!modules.length){toast('Enable at least one module for this event.');return}
 if(!name||name.length<3){toast('Enter an event name of at least 3 characters.');return}
 if(!/^[A-Z0-9-]{4,16}$/.test(code||'')){toast('Use a code of 4–16 letters, numbers or hyphens.');return}
 if(db.events.some(e=>e.code===code&&e.id!==editingEventId)){toast('This event code already exists.');return}
 const nextId=editingEventId||'evt-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
 updateDatabase(d=>{const item=d.events.find(e=>e.id===nextId);if(item){const old=categoryOf(item);Object.assign(item,{name,code,venue,date,status,category,visibility,modules});item.state.eventName=name.toUpperCase();if(old!==category){item.state.pollBank=defaultBank(category);item.state.poll=Object.assign(item.state.poll,{...item.state.pollBank[0],votes:new Array(item.state.pollBank[0].options.length).fill(0),open:false})}}else{const ne=makeSeedEvent(nextId,code,name,venue,date,category,status);ne.visibility=visibility;ne.modules=modules;d.events.push(ne)}});
 editingEventId=null;selectOrganiser(nextId);tab='events';draw();toast('Event saved: '+name);break;}
case'activate-solid':update(s=>{s.lightMode='solid';s.lightStarted=0});toast('Crowd colour activated for '+event.name);break;
case'start-sequence':update(s=>{s.lightMode='sequence';s.sequenceId='aurora';s.lightStarted=Date.now()+900;s.lightLaunchCount++});toast('Aurora Wave scheduled for '+event.name);break;
case'stop-light':update(s=>{s.lightMode='idle';s.lightStarted=0});toast('Light show stopped');break;
case'save-poll':{const q=document.getElementById('poll-question')?.value.trim();const opts=[0,1,2].map(i=>document.getElementById('poll-option-'+i)?.value.trim());if(!q||opts.some(a=>!a)){toast('Question and all three options are required.');return;}update(s=>{s.poll.question=q;s.poll.options=opts});toast('Poll question saved for '+event.name);break}
case'launch-poll':{const q=document.getElementById('poll-question')?.value.trim()||state.poll.question,opts=[0,1,2].map(i=>document.getElementById('poll-option-'+i)?.value.trim()||state.poll.options[i]);update(s=>{s.poll={type:'choice',question:q,options:opts,votes:new Array(opts.length).fill(0),open:true,version:s.poll.version+1};s.pollLaunchCount++;s.sponsorActive=false});stageMode='poll';toast('Live poll launched for '+event.name);break}
case'close-poll':update(s=>{s.poll.open=false});toast('Poll closed');break;
case'launch-quiz':if(!enabledFor(event,'quiz'))return;update(s=>{s.quiz.open=true;s.quiz.version++});toast('Trivia round is live');break;
case'close-quiz':update(s=>{s.quiz.open=false});toast('Trivia round closed');break;
case'send-announcement':{
 const message=document.getElementById('announcement-body')?.value.trim();
 const zone=document.getElementById('announcement-target')?.value||'all';
 if(!message){toast('Please write an announcement.');return;}
 if(!['all',...DEMO_ZONES].includes(zone)){toast('Choose a valid audience zone.');return;}
 if(zone!=='all'&&!enabledFor(event,'seating')){toast('Enable Seat & zone check-in before sending a targeted message.');return;}
 const entry={id:'announcement-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),zone,text:message,date:Date.now(),active:true};
 update(s=>{s.messages.push(entry);s.messagesSent++;if(zone==='all'){s.announcement=message;s.announcementSent=true;}});
 toast(zone==='all'?'Announcement posted for all attendees.':'Announcement posted to '+zone+' zone (confirmed seats only).');break;
}
case'clear-announcement':update(s=>{s.announcementSent=false;s.messages.forEach(m=>m.active=false)});toast('Active banners cleared; history retained.');break;
case'launch-sponsor':update(s=>s.sponsorActive=true);toast('Sponsor moment active');break;
case'close-sponsor':update(s=>s.sponsorActive=false);toast('Sponsor moment ended');break;
case'activate-offer':update(s=>s.sponsorActive=true);toast('Demo reward published');break;
case'set-display-poll':stageMode='poll';draw();break;

case'copy-event-link':{navigator.clipboard?.writeText(shareUrl(event)).then(()=>toast('Invite link copied')).catch(()=>toast('Copy this event URL from the Invite attendees panel.'));break}
case'save-event-qr':{const svg=realQR(shareUrl(event));const blob=new Blob([svg],{type:'image/svg+xml'});downloadContent(blob,'harmoniq-'+event.code+'-QR.svg');toast('Scannable event QR saved');break}
case'add-poll-question':{const type=document.getElementById('poll-type')?.value||'choice',question=document.getElementById('poll-question')?.value.trim(),options=type==='yesno'?['Yes','No']:[0,1,2].map(i=>document.getElementById('poll-option-'+i)?.value.trim());if(!question||options.some(x=>!x)){toast('Enter a question and all its answer choices.');return}update(s=>{s.pollBank.push({type,question,options})});toast('Question saved for this event');break}
case'save-sponsor':{const name=document.getElementById('sponsor-name')?.value.trim(),headline=document.getElementById('sponsor-headline')?.value.trim(),offer=document.getElementById('sponsor-offer')?.value.trim(),expiry=document.getElementById('sponsor-expiry')?.value||'',limit=Number(document.getElementById('sponsor-limit')?.value||0);if(!name||!headline||!offer||limit<1||limit>999){toast('Complete all sponsor fields and set a valid limit.');return}update(s=>{s.sponsor={name,headline,offer,expiry,limit}});toast('Sponsor campaign saved');break}
case'claim-offer':{if(!enabledFor(event,'rewards'))return;if(!state.sponsorActive){toast('Offer has not been published yet');return}let entry=state.claims.find(c=>c.session===sessionId);if(entry){toast('Offer already claimed');return}if(state.sponsor.expiry&&state.sponsor.expiry<new Date().toISOString().slice(0,10)){toast('Offer expired');return}if(state.claims.filter(c=>c.used).length>=state.sponsor.limit){toast('Offer redemption limit reached');return}const code='HM-'+Math.random().toString(36).slice(2,8).toUpperCase();update(s=>{s.claims.push({code,session:sessionId,used:false,date:Date.now()})});toast('Demo claim generated: '+code);break}
case'redeem-offer':{const code=document.getElementById('redeem-code')?.value.trim().toUpperCase();const claim=state.claims.find(c=>c.code===code);if(!claim){toast('Claim not found for this event');return}if(claim.used){toast('Already redeemed');return}if(state.sponsor.expiry&&state.sponsor.expiry<new Date().toISOString().slice(0,10)){toast('Offer expired');return}if(state.claims.filter(c=>c.used).length>=state.sponsor.limit){toast('Redemption limit reached');return}update(s=>{const c=s.claims.find(x=>x.code===code);if(c)c.used=true});toast('Demo claim validated');break}
case'export-event-report':{const r=selectedReport(event);let rows=[['Harmoniq prototype report','Value'],['Event',event.name],['Event code',event.code],['Type',TYPES[categoryOf(event)].label],['Note','Browser-local demo; attendee baseline may be illustrative'],...Object.entries(r)];const csv=rows.map(a=>a.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');downloadContent(new Blob([csv],{type:'text/csv;charset=utf-8'}),'harmoniq-'+event.code+'-report.csv');toast('Demo report downloaded');break}
case'set-display-quiz':stageMode='quiz';draw();break;
case'fullscreen':{const e=document.documentElement;if(!document.fullscreenElement){e.requestFullscreen?.()}else{document.exitFullscreen?.()}break}
case'reset-demo':{update(s=>Object.assign(s,newEventState(event.name,event.id==='evt-midnight')));toast('Selected event reset: '+event.name);break;}
}}
// ----------- Harmoniq V3 demonstration modules -----------
// Browser-local prototype only. It never uses GPS and does not transmit data to a backend.
const DEMO_ZONES=['North','South','East','West','VIP'];
const VENUES=[
 {id:'ember',name:'Ember Kitchen',cuisine:'Grill & bowls'},
 {id:'garden',name:'Green Garden',cuisine:'Vegetarian'},
 {id:'slice',name:'The Slice Co.',cuisine:'Pizza & street food'}
];
const FOOD_CATALOG=[
 {id:'chicken',vendor:'ember',name:'Grilled chicken rice bowl',price:12.5,veg:false,spicy:false,kcal:580,allergens:'Soy, sesame'},
 {id:'spicy',vendor:'ember',name:'Spicy loaded fries',price:8.5,veg:true,spicy:true,kcal:670,allergens:'Milk, wheat'},
 {id:'falafel',vendor:'garden',name:'Falafel & hummus wrap',price:9.0,veg:true,spicy:false,kcal:490,allergens:'Sesame, wheat'},
 {id:'salad',vendor:'garden',name:'Roasted vegetable salad',price:10.0,veg:true,spicy:false,kcal:320,allergens:'Nuts (may contain)'},
 {id:'pizza',vendor:'slice',name:'Margherita pizza',price:11.0,veg:true,spicy:false,kcal:760,allergens:'Milk, wheat'},
 {id:'pepper',vendor:'slice',name:'Hot pepper pizza',price:13.5,veg:false,spicy:true,kcal:830,allergens:'Milk, wheat'}
];
const pounds=n=>'£'+Number(n).toFixed(2);
let foodPrefs={budget:15,vegetarian:false,spicy:false,vendor:'all'};
let preparedSeat={zone:'North',row:'3',seat:'12'};
let torchStream=null,torchTrack=null,torchActive=false;
let qrStream=null,qrTimer=null;
const seatPath=(zone,row,seat)=>[zone,row,seat].map(t=>String(t||'').trim());
const seatCode=(zone,row,seat)=>seatPath(zone,row,seat).join('|');
const seatLabel=s=>s?`Zone ${s.zone} · Row ${s.row} · Seat ${s.seat}`:'Seat not confirmed';
function guestSeat(){return (state.seatCheckins||{})[sessionId]||null}
function myOrders(){return (state.foodOrders||[]).filter(o=>o.session===sessionId).slice().reverse()}
function matchesZone(m,seat){return m.zone==='all'||(seat&&seat.confirmed&&m.zone===seat.zone)}
function visibleAudienceMessages(){return (state.messages||[]).filter(m=>matchesZone(m,guestSeat()))}
function latestAudienceMessage(){return visibleAudienceMessages().filter(m=>m.active!==false).at(-1)||null}
function latestZoneMessage(){return latestAudienceMessage()}
function seatUrl(e,zone,row,seat){return shareUrl(e)+'&seat='+encodeURIComponent(seatCode(zone,row,seat))}
function zoneOption(current='all'){return ['all',...DEMO_ZONES].map(z=>`<option value="${esc(z)}" ${current===z?'selected':''}>${z==='all'?'All zones':z}</option>`).join('')}
function orderStatus(o){return ({placed:'Order placed',preparing:'Preparing',ready:'Ready for collection',collected:'Collected',location_requested:'Restaurant requested your seat location',courier:'On the way to your seat',delivered:'Delivered to seat'})[o.status]||o.status}
function stopTorch(){try{torchStream?.getTracks().forEach(t=>t.stop())}catch(e){}torchStream=null;torchTrack=null;torchActive=false}
async function toggleTorch(){
 if(torchActive){stopTorch();draw();toast('Flashlight turned off');return}
 if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){toast('Flashlight needs HTTPS, camera permission and supported hardware.');return}
 try{
  stopSeatCamera();const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const track=stream.getVideoTracks()[0];
  if(!track?.getCapabilities?.().torch){stream.getTracks().forEach(t=>t.stop());toast('Torch not supported on this browser/device. Use screen light instead.');return}
  await track.applyConstraints({advanced:[{torch:true}]});torchStream=stream;torchTrack=track;torchActive=true;draw();toast('Flashlight on · steady light only');
 }catch(err){stopTorch();toast('Flashlight unavailable: camera permission, browser or hardware limitation.')}
}
function stopSeatCamera(){if(qrTimer){clearInterval(qrTimer);qrTimer=null}try{qrStream?.getTracks().forEach(x=>x.stop())}catch(e){}qrStream=null}
function applySeat(zone,row,seat,source='manual',confirmed=true){
 const p=seatPath(zone,row,seat);if(!DEMO_ZONES.includes(p[0])||!/^\d{1,3}$/.test(p[1])||!/^\d{1,4}$/.test(p[2])){toast('Choose a valid zone and numeric row/seat.');return false}
 update(s=>{const verified={zone:p[0],row:p[1],seat:p[2],confirmed,source,updated:Date.now()};s.seatCheckins[sessionId]=verified;if(confirmed)for(const order of s.foodOrders){if(order.session===sessionId&&order.service==='delivery'&&order.status==='location_requested'){order.seat={...verified};order.status='preparing'}}});toast(confirmed?'Seat check-in confirmed':'Assigned seat loaded. Tap I am seated to confirm.');return true
}
function useSeatQR(raw){
 try{const u=new URL(raw,location.href),code=u.searchParams.get('event'),seat=u.searchParams.get('seat');if(!code||code!==event.code||!seat){toast('This is not a seat QR for your current event.');return false}
 const p=seat.split('|');if(p.length!==3)return false;stopSeatCamera();return applySeat(p[0],p[1],p[2],'qr-scan',true)
 }catch(e){toast('Invalid seat QR. Enter seat details instead.');return false}
}
async function beginSeatCamera(){
 if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia||!('BarcodeDetector' in window)){toast('Camera QR scanning unsupported here. Use the seat link or enter the seat code manually.');return}
 try{
  stopTorch();stopSeatCamera();const kinds=await BarcodeDetector.getSupportedFormats?.();if(kinds&&!kinds.includes('qr_code'))throw Error('qr_code unsupported');
  qrStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const video=document.getElementById('seat-video');if(!video){stopSeatCamera();return}video.srcObject=qrStream;await video.play();const detector=new BarcodeDetector({formats:['qr_code']});
  qrTimer=setInterval(async()=>{if(!video||!qrStream||video.readyState<2)return;try{const found=await detector.detect(video);if(found.length){useSeatQR(found[0].rawValue)}}catch(e){}},500);
  toast('Point the camera at the seat QR.');
 }catch(e){stopSeatCamera();toast('Cannot scan QR on this device. You can enter the seat manually.')}
}
function seatAdmin(){const seats=Object.entries(state.seatCheckins||{}).filter(([,seat])=>seat.confirmed);return `${heading('GUIDE / SEAT CHECK-IN','Seats & zones','Preassign seats to ticket references or create a seat QR. A QR alone is not proof of physical presence.')}
<div class="grid-3" style="margin-bottom:20px">${stat(seats.length,'Confirmed seats','Browser demo sessions')}${stat(state.seatAssignments.length,'Preassigned tickets','Event-local')}${stat(DEMO_ZONES.length,'Configured zones','Demonstration layout')}</div>
<div class="panel"><h2>Generate a seat QR / seat link</h2><p class="descr">Show this QR on a seat label or scan its attendee link. Zone, row and seat are encoded in the URL.</p><div class="event-form"><div class="field"><label>Venue zone</label><select class="input" id="seat-admin-zone">${zoneOption(preparedSeat.zone).replace('<option value="all" >All zones</option>','')}</select></div><div class="field"><label>Row</label><input class="input" id="seat-admin-row" value="${esc(preparedSeat.row)}" inputmode="numeric"></div><div class="field"><label>Seat</label><input class="input" id="seat-admin-seat" value="${esc(preparedSeat.seat)}" inputmode="numeric"></div></div><div class="row"><button class="btn" data-action="make-seat-qr">Generate seat QR</button><button class="btn secondary" data-action="copy-seat-url">Copy seat link</button></div>
<div class="share-row" style="margin-top:20px"><div class="qr-real seat-qr">${realQR(seatUrl(event,preparedSeat.zone,preparedSeat.row,preparedSeat.seat),175)}</div><div style="flex:1"><div class="kicker">CURRENT DEMO SEAT</div><h3>${esc(seatLabel(preparedSeat))}</h3><p class="mono">${esc(seatUrl(event,preparedSeat.zone,preparedSeat.row,preparedSeat.seat))}</p><p class="small muted">A guest scans the code and confirms seating in the event. Requires a real attendee backend for cross-device visibility.</p></div></div></div>
<div class="panel"><h2>Preassign a ticket seat</h2><p class="descr">Guests can enter their ticket reference, see the allocated seat, then tap “I'm seated”.</p><div class="field"><label>Ticket reference</label><input class="input" id="ticket-code-admin" placeholder="e.g. TKT-104" maxlength="30"></div><div class="row"><button class="btn secondary" data-action="preassign-seat">Allocate current seat to ticket</button></div><div class="ops-list" style="margin-top:16px">${state.seatAssignments.length?state.seatAssignments.slice(-8).reverse().map(a=>`<div class="scene-row"><b>${esc(a.ticket)}</b><span>${esc(seatLabel(a))}</span></div>`).join(''):'<p class="small muted">No preassigned tickets yet.</p>'}</div></div>
<div class="panel"><h2>Checked-in seats (demo)</h2><div class="ops-list">${seats.length?seats.map(([session,s])=>`<div class="ops-card"><b>${esc(seatLabel(s))}</b><p class="small muted">Session ${esc(session.slice(0,14))}… · ${esc(s.source)}</p></div>`).join(''):'<p class="small muted">No confirmed seats. Join as attendee and check in to see one here.</p>'}</div></div>`}
function foodAdmin(){const orders=state.foodOrders.slice().reverse();return `${heading('DINE / RESTAURANT OPERATIONS','Food operations','Simulate kitchen preparation, pickup notification and delivery to a confirmed seat. No real orders or payments.')}
<div class="grid-3" style="margin-bottom:20px">${stat(orders.length,'Orders received','Browser demo')}${stat(orders.filter(o=>o.status==='ready').length,'Ready for pickup','Requires staff action')}${stat(orders.filter(o=>o.service==='delivery').length,'Seat deliveries','Location from check-in')}</div>
<div class="panel"><h2>Restaurant order board</h2><p class="descr">Three fictional vendors · six demo menu items. Staff can advance status and the attendee order page displays the update.</p><div class="ops-list">${orders.length?orders.map(o=>`<div class="ops-card"><div class="row"><b>${esc(o.id)} · ${esc(o.itemName)}</b><span class="microtag">${esc(orderStatus(o))}</span></div><p class="small muted">${esc(o.vendorName)} · ${pounds(o.price)} · ${o.service==='delivery'?'Seat delivery · '+esc(seatLabel(o.seat)):'Pick up at '+esc(o.vendorName)}</p><div class="row">${o.status==='placed'?`<button class="btn secondary small-btn" data-food-status="${esc(o.id)}" data-status="preparing">Start preparing</button>`:''}${o.status==='preparing'?`<button class="btn small-btn" data-food-status="${esc(o.id)}" data-status="${o.service==='pickup'?'ready':'courier'}">${o.service==='pickup'?'Mark ready · notify guest':'Dispatch to seat · notify guest'}</button>`:''}${o.status==='ready'?`<button class="btn secondary small-btn" data-food-status="${esc(o.id)}" data-status="collected">Mark collected</button>`:''}${o.service==='delivery'&&['placed','preparing'].includes(o.status)?`<button class="btn ghost small-btn" data-food-status="${esc(o.id)}" data-status="location_requested">Request guest seat / location</button>`:''}${o.status==='courier'?`<button class="btn secondary small-btn" data-food-status="${esc(o.id)}" data-status="delivered">Mark delivered</button>`:''}</div></div>`).join(''):'<div class="mini-empty">No orders yet. Open the attendee Food & Dining section to place a demo order.</div>'}</div></div>
<div class="notice-warn">This is a simulation. Kitchen staff, delivery couriers, POS, verified allergen records and real-time cross-device notifications are not connected.</div>`}
function seatGuestHtml(back){const s=guestSeat();return `${back}<div class="eyebrow">GUIDE / SEAT CHECK-IN</div><h2>Find and confirm your seat.</h2><p>Share your event area voluntarily to receive local updates and request seat delivery. No GPS tracking.</p>${s?`<div class="seat-mark"><strong>${esc(seatLabel(s))}</strong><span>${s.confirmed?'✓ Confirmed':'Awaiting confirmation'}</span></div>`:''}
<div class="field"><label>Ticket reference (preassigned)</label><input class="input" id="guest-ticket" maxlength="30" placeholder="e.g. TKT-104"></div><button class="btn secondary phone-action" data-action="find-ticket-seat">Find assigned seat</button>
<div class="field"><label>Zone / stand</label><select id="guest-seat-zone" class="input">${DEMO_ZONES.map(z=>`<option value="${z}" ${s?.zone===z?'selected':''}>${z}</option>`).join('')}</select></div>
<div class="filter-grid"><div class="field"><label>Row</label><input id="guest-seat-row" class="input" inputmode="numeric" value="${esc(s?.row||'3')}"></div><div class="field"><label>Seat</label><input id="guest-seat-num" class="input" inputmode="numeric" value="${esc(s?.seat||'12')}"></div></div>
<button class="btn phone-action" data-action="confirm-my-seat">✓ I'm seated here</button>
<button class="btn secondary phone-action" data-action="scan-seat-qr">Scan seat QR with camera</button><video id="seat-video" class="camera-preview" autoplay playsinline muted></video><button class="btn ghost phone-action" data-action="stop-seat-camera">Stop camera</button>
<p class="small muted">If scanning is unavailable, open the seat QR link or enter details above. Scanning is not independently verified proof of attendance.</p>`}
function guestFoodHtml(back){const s=guestSeat();const results=FOOD_CATALOG.filter(x=>x.price<=foodPrefs.budget&&(!foodPrefs.vegetarian||x.veg)&&(!foodPrefs.spicy||x.spicy)&&(foodPrefs.vendor==='all'||x.vendor===foodPrefs.vendor));const sorted=results.slice().sort((a,b)=>(Number(b.spicy===foodPrefs.spicy)+Number(b.veg===foodPrefs.vegetarian))*1.5-(Number(a.spicy===foodPrefs.spicy)+Number(a.veg===foodPrefs.vegetarian))*1.5||a.price-b.price);const currentOrders=myOrders();return `${back}<div class="eyebrow">DINE / FOOD DISCOVERY</div><h2>Food & Dining</h2><p>Explore illustrative menus from venue restaurants. Filters provide rule-based suggestions, not AI advice or verified allergy safety.</p>
<div class="field"><label>Maximum budget</label><select class="input" id="food-budget">${[10,15,20,30].map(n=>`<option value="${n}" ${foodPrefs.budget===n?'selected':''}>Up to £${n}</option>`).join('')}</select></div>
<div class="field"><label>Restaurant</label><select class="input" id="food-vendor"><option value="all">All restaurants</option>${VENUES.map(v=>`<option value="${v.id}" ${foodPrefs.vendor===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div>
<label class="small"><input type="checkbox" id="food-vegetarian" ${foodPrefs.vegetarian?'checked':''}> Vegetarian</label> &nbsp; <label class="small"><input type="checkbox" id="food-spicy" ${foodPrefs.spicy?'checked':''}> Prefer spicy</label>
<button class="btn secondary phone-action" data-action="suggest-food">Show matching food →</button><div class="eyebrow" style="margin-top:22px">SUGGESTED FROM DEMO MENU · ${sorted.length} MATCHES</div>
<div class="food-grid">${sorted.map(f=>{let v=VENUES.find(x=>x.id===f.vendor);return `<div class="food-card"><b>${esc(f.name)}</b><p>${esc(v.name)} · ${esc(v.cuisine)}<br/>${f.veg?'Vegetarian · ':''}${f.spicy?'Spicy · ':''}${f.kcal} kcal (sample)</p><span class="price">${pounds(f.price)}</span><p>Vendor-supplied allergens (illustrative): ${esc(f.allergens)}</p><button class="btn" data-food-order="${esc(f.id)}">Order demo →</button></div>`}).join('')||'<div class="notice-warn">No menu matches these filters. Increase your budget or change preferences.</div>'}</div>
${!s?.confirmed?'<div class="notice-warn">Seat delivery requires a confirmed seat in Seat & Zone. You can still choose collection.</div>':`<div class="seat-mark">Delivery address: ${esc(seatLabel(s))}</div>`}
<div class="eyebrow">MY ORDERS</div>${currentOrders.length?currentOrders.map(o=>`<div class="order-status"><b>${esc(o.id)} · ${esc(o.itemName)}</b><p style="margin:6px 0">${esc(orderStatus(o))}</p><small>${o.service==='pickup'?'Collect at '+esc(o.vendorName):'Delivery to '+esc(seatLabel(o.seat))}</small>${o.status==='ready'?'<p style="color:#83efc7">🔔 Your order is ready. Visit the restaurant pickup counter.</p>':''}${o.status==='courier'?'<p style="color:#83efc7">🔔 Staff are bringing your order to your confirmed seat.</p>':''}${o.status==='location_requested'?'<div class="notice-warn">📍 Restaurant asks: Where are you seated? Please confirm your location to proceed.</div><button class="btn secondary phone-action" data-mobile="seat">Confirm delivery location →</button>':''}</div>`).join(''):'<p class="small muted">No orders yet.</p>'}
<div class="notice-warn">No real payment, food order, courier tracking or verified allergy advice. Always confirm ingredients and allergens directly with the venue.</div>`}
let selectedFood=null;
function foodCheckoutHtml(back){const f=FOOD_CATALOG.find(x=>x.id===selectedFood);if(!f){audiencePage='food';return guestFoodHtml(back)}const v=VENUES.find(x=>x.id===f.vendor),s=guestSeat();return `${back}<div class="eyebrow">DINE / CHECKOUT DEMO</div><h2>Confirm demo order</h2><div class="food-card"><b>${esc(f.name)}</b><p>${esc(v.name)} · Vendor allergen example: ${esc(f.allergens)}</p><span class="price">${pounds(f.price)}</span></div>
<div class="field" style="margin-top:17px"><label>Fulfilment method</label><select class="input" id="food-service"><option value="pickup">Pick up at restaurant</option><option value="delivery" ${s?.confirmed?'':'disabled'}>Bring to my confirmed seat ${s?.confirmed?'('+esc(seatLabel(s))+')':'(check-in first)'}</option></select></div>
<div class="notice">Payment is not taken. Choosing Place demo order records a simulated order in this browser only.</div><button class="btn phone-action" data-action="place-food-order">Place demo order →</button>`}
function extendedPhone(compact){const back=`<button class="phone-back" data-mobile="home">← Back to event</button>`;const html=audiencePage==='seat'?seatGuestHtml(back):audiencePage==='food'?guestFoodHtml(back):foodCheckoutHtml(back);return `<div class="phone"><div class="phone-main">${html}</div><div class="phone-footer"><button data-mobile="home">Home</button><button data-mobile="seat" class="${audiencePage==='seat'?'selected':''}">My seat</button><button data-mobile="food" class="${audiencePage==='food'?'selected':''}">Food</button></div></div>`}
const previousPhoneHtml=phoneHtml;
phoneHtml=function(compact=true){
 if(['seat','food','food-checkout'].includes(audiencePage)){if(!compact&&!joined)return previousPhoneHtml(false);return extendedPhone(compact)}
 let html=previousPhoneHtml(compact);
 if(audiencePage==='home'){
  const order=myOrders().find(o=>o.status==='ready'||o.status==='courier'||o.status==='location_requested');
  const notice=order?`<button class="phone-banner" data-mobile="food" style="width:100%;color:#b6f5df;text-align:left;border:1px solid #39786b">🔔 ${esc(orderStatus(order))}: ${esc(order.itemName)} →</button>`:'';
  html=html.replace('<h2>Welcome to your event.</h2>','<h2>Welcome to your event.</h2>'+notice);
  let tiles='';if(enabledFor(event,'seating'))tiles+='<button class="phone-tile" data-mobile="seat">⌖<b>Seat & zone</b><span>Check in at your seat</span></button>';
  if(enabledFor(event,'food'))tiles+='<button class="phone-tile" data-mobile="food">🍽<b>Food & Dining</b><span>Menus & order status</span></button>';
  html=html.replace('<div class="phone-tile-grid">','<div class="phone-tile-grid">'+tiles);
 }
 
 if(audiencePage==='lights'&&enabledFor(event,'lights')){
  const label=torchActive?'🔦 Turn flashlight off':'🔦 Enable steady flashlight';
  if(state.lightMode!=='idle'&&!currentLight().done)html=html.replace('<button class="btn secondary" data-mobile="home">Exit light mode ×</button>',`<button class="btn torch-action" data-action="toggle-flashlight">${label}</button><button class="btn secondary" data-mobile="home">Exit light mode ×</button>`);
  else html=html.replace('<div class="notice-warn">Opt-in visual effect demo.',`<button class="btn phone-action" data-action="toggle-flashlight">${label}</button><div class="torchnote">Torch requires an HTTPS-enabled mobile browser and a supported rear camera. If unavailable, use screen lighting. No strobe/flashing effect.</div><div class="notice-warn">Opt-in visual effect demo.`);
 }
 return html
};
const previousHandle=handleAction;
handleAction=function(action){
 switch(action){
 case 'make-seat-qr':{
 const z=document.getElementById('seat-admin-zone')?.value,r=document.getElementById('seat-admin-row')?.value,s=document.getElementById('seat-admin-seat')?.value;
 if(!DEMO_ZONES.includes(z)||!/^\d{1,3}$/.test(r||'')||!/^\d{1,4}$/.test(s||'')){toast('Choose zone, numeric row and seat.');return}
 preparedSeat={zone:z,row:r,seat:s};draw();toast('New seat QR generated for '+seatLabel(preparedSeat));return
 }
 case 'copy-seat-url':navigator.clipboard?.writeText(seatUrl(event,preparedSeat.zone,preparedSeat.row,preparedSeat.seat)).then(()=>toast('Seat link copied')).catch(()=>toast('Copy URL displayed beside the QR'));return;
 case 'preassign-seat':{
 const ticket=document.getElementById('ticket-code-admin')?.value.trim().toUpperCase();if(!ticket){toast('Enter a ticket reference first.');return}update(s=>{const a=s.seatAssignments.find(x=>x.ticket===ticket);if(a)Object.assign(a,{...preparedSeat});else s.seatAssignments.push({ticket,...preparedSeat})});toast('Seat assigned to '+ticket);return
 }
 case 'find-ticket-seat':{
 const t=document.getElementById('guest-ticket')?.value.trim().toUpperCase(),s=state.seatAssignments.find(x=>x.ticket===t);if(!s){toast('Ticket reference not found in this event.');return}applySeat(s.zone,s.row,s.seat,'preassigned-ticket',false);return
 }
 case 'confirm-my-seat':{
 const zone=document.getElementById('guest-seat-zone')?.value,row=document.getElementById('guest-seat-row')?.value,seat=document.getElementById('guest-seat-num')?.value;applySeat(zone,row,seat,'guest-check-in',true);return
 }
 case 'scan-seat-qr':beginSeatCamera();return;
 case 'stop-seat-camera':stopSeatCamera();toast('Scanner stopped');return;
 case 'suggest-food':{
 foodPrefs={budget:Number(document.getElementById('food-budget')?.value||15),vendor:document.getElementById('food-vendor')?.value||'all',vegetarian:!!document.getElementById('food-vegetarian')?.checked,spicy:!!document.getElementById('food-spicy')?.checked};draw();return
 }
 case 'place-food-order':{
 const f=FOOD_CATALOG.find(x=>x.id===selectedFood);if(!f)return;const v=VENUES.find(x=>x.id===f.vendor),service=document.getElementById('food-service')?.value||'pickup',seat=guestSeat();
 if(service==='delivery'&&!seat?.confirmed){toast('Confirm your seat before requesting delivery.');return}
 const id='FD-'+Date.now().toString(36).toUpperCase().slice(-7);update(s=>s.foodOrders.push({id,session:sessionId,item:f.id,itemName:f.name,vendor:f.vendor,vendorName:v.name,price:f.price,service,seat:service==='delivery'?{...seat}:null,status:'placed',created:Date.now()}));selectedFood=null;audiencePage='food';draw();toast('Demo order '+id+' placed · no payment charged');return
 }
 case 'toggle-flashlight':toggleTorch();return;
 }
 return previousHandle(action)
};
// Listener capture intercepts new actions without interfering with the original event delegation.
document.addEventListener('click',e=>{
 const n=e.target.closest('[data-food-order],[data-food-status]');if(!n)return;
 e.stopImmediatePropagation();e.preventDefault();
 if(n.dataset.foodOrder){if(!enabledFor(event,'food'))return;selectedFood=n.dataset.foodOrder;audiencePage='food-checkout';draw();return}
 const id=n.dataset.foodStatus,next=n.dataset.status,allowed={placed:['preparing','location_requested'],preparing:['ready','courier','location_requested'],location_requested:[],ready:['collected'],courier:['delivered']};
 const order=state.foodOrders.find(o=>o.id===id);if(!order||!(allowed[order.status]||[]).includes(next))return;
 if(order.service==='pickup'&&!['preparing','ready','collected'].includes(next))return;
 if(order.service==='delivery'&&!['preparing','courier','delivered','location_requested'].includes(next))return;
 update(s=>{const o=s.foodOrders.find(x=>x.id===id);if(o)o.status=next});toast('Order '+id+': '+orderStatus({...order,status:next}));
},true);
// Dedicated capture for seat QR, orders and torch so the original UI still handles other buttons.
document.addEventListener('click',e=>{
 const n=e.target.closest('[data-action]');if(!n)return;
 const handled=['make-seat-qr','copy-seat-url','preassign-seat','find-ticket-seat','confirm-my-seat','scan-seat-qr','stop-seat-camera','suggest-food','place-food-order','toggle-flashlight'];
 if(handled.includes(n.dataset.action)){e.stopImmediatePropagation();e.preventDefault();handleAction(n.dataset.action)}
},true);
const oldJoin=joinEventByCode;
joinEventByCode=function(code){const ok=oldJoin(code);if(ok&&QS.has('seat')){
 const seat=QS.get('seat').split('|');if(seat.length===3)applySeat(seat[0],seat[1],seat[2],'seat-qr-link',true)
 }return ok};
const oldLeave=leaveEvent;
leaveEvent=function(){stopSeatCamera();stopTorch();oldLeave()};
const oldEnter=enterMobile;
enterMobile=function(page){if(page!=='seat')stopSeatCamera();if(page!=='lights')stopTorch();oldEnter(page)};
const oldNav=nav;
nav=function(page){if(page!=='attendee'){stopSeatCamera();stopTorch()}oldNav(page)};
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopSeatCamera();stopTorch()}});
// Migration for reloaded tabs: readDatabase/upgradeEvent ensure every event has the additional fields.

window.addEventListener('click',e=>{
const a=e.target.closest('[data-action],[data-tab],[data-mobile],[data-vote],[data-quiz],[data-color],[data-view],[data-join-code],[data-select-event],[data-edit-event],[data-toggle-event],[data-run-question],[data-sequence],[data-feedback]');if(!a)return;
if(a.dataset.action){handleAction(a.dataset.action);return}
if(a.dataset.runQuestion!==undefined){const i=Number(a.dataset.runQuestion);update(s=>{const q=s.pollBank[i];if(!q)return;if(s.poll&&s.poll.votes.some(v=>v>0))s.pollArchive.push({question:s.poll.question,options:clone(s.poll.options),votes:clone(s.poll.votes)});s.poll={...clone(q),votes:new Array(q.options.length).fill(0),open:true,version:s.poll.version+1};s.pollIndex=i;s.pollLaunchCount++;s.sponsorActive=false});stageMode='poll';toast('Question '+(i+1)+' now live');return}
if(a.dataset.sequence){const k=a.dataset.sequence;if(!enabledFor(event,'lights')||!SEQUENCES[k])return;update(s=>{s.lightMode='sequence';s.sequenceId=k;s.lightStarted=Date.now()+600;s.lightLaunchCount++});toast(SEQUENCES[k].name+' started');return}
if(a.dataset.feedback){if(!enabledFor(event,'analytics'))return;const value=Number(a.dataset.feedback);if(!(value>=1&&value<=5))return;if(state.feedback.some(x=>x.session===sessionId))return;update(s=>s.feedback.push({session:sessionId,rating:value,date:Date.now()}));toast('Thanks for your demo feedback');return}
if(a.dataset.joinCode){joinEventByCode(a.dataset.joinCode);return}
if(a.dataset.selectEvent){selectOrganiser(a.dataset.selectEvent);tab='overview';draw();return}
if(a.dataset.editEvent){editingEventId=a.dataset.editEvent;tab='events';draw();setTimeout(()=>document.getElementById('manage-event-name')?.focus(),50);return}
if(a.dataset.toggleEvent){const id=a.dataset.toggleEvent;updateDatabase(d=>{const e=d.events.find(e=>e.id===id);if(e)e.status=e.status==='live'?'draft':'live';});toast('Event entry status changed');return}
if(a.dataset.tab){tab=a.dataset.tab;draw();return}
if(a.dataset.mobile){const k=({seat:'seating',sponsor:'sponsors',reward:'rewards',announcement:'announcements',feedback:'analytics'})[a.dataset.mobile]||a.dataset.mobile;if(MODULES[k]&&!enabledFor(event,k)){toast('This experience is disabled for this event');return}enterMobile(a.dataset.mobile);return}
if(a.dataset.view){nav(a.dataset.view);return}
if(a.dataset.color){update(s=>s.color=COLORS[a.dataset.color]);return}
if(a.dataset.vote){if(!enabledFor(event,'poll'))return;if(!joined&&view==='attendee'){toast('Join an event before voting.');return;}if(!state.poll.open){toast('Poll is not open yet.');return;}const token='harmoniq-vote-'+event.id+'-'+state.poll.version;if(sessionStorage.getItem(token)==='1'){toast('You already voted in this round.');return;}let i=Number(a.dataset.vote);sessionStorage.setItem(token,'1');update(s=>s.poll.votes[i]++);toast('Vote recorded for '+event.name);return}
if(a.dataset.quiz){if(!enabledFor(event,'quiz'))return;if(!joined&&view==='attendee'){toast('Join an event before playing.');return;}if(!state.quiz.open){toast('The quiz has not started yet.');return;}const token='harmoniq-quiz-'+event.id+'-'+state.quiz.version;if(sessionStorage.getItem(token)!=null)return;sessionStorage.setItem(token,a.dataset.quiz);update(s=>s.quizResponses++);draw();toast(Number(a.dataset.quiz)===state.quiz.correct?'Correct answer! +100 demo points':'Thanks for taking part!');return}
});
window.addEventListener('change',e=>{if(e.target.id==='organiser-event-switch'){selectOrganiser(e.target.value);return}if(e.target.id==='display-event-switch'){selectDisplay(e.target.value);return}if(e.target.id==='manage-event-category'){const c=TYPES[e.target.value]||TYPES.concert;document.querySelectorAll('[data-event-module]').forEach(x=>x.checked=c.modules.includes(x.dataset.eventModule));return}if(e.target.id==='poll-type'){const isYes=e.target.value==='yesno';document.getElementById('poll-option-fields').style.display=isYes?'none':'';return}});

setInterval(()=>{if(state.lightMode==='sequence'){if(currentLight().done){update(s=>{if(s.lightMode==='sequence'&&(Date.now()-s.lightStarted)>=(SEQUENCES[s.sequenceId]?.duration||16)*1000){s.lightMode='idle';s.lightStarted=0}})}else if(view==='display'||(view==='attendee'&&audiencePage==='lights')||(view==='studio'&&(tab==='lights'||audiencePage==='lights')))draw()}},900);
draw();
})();
